  (d^3*el^6*Op*(mtad[{0, mass[MW], mass[MW]}, {0, 1, 1}]/
      (mass[MW]^4*(mass[MW] - mass[MZ])*(mass[MW] + mass[MZ])) + 
     mtad[{0, mass[MZ], mass[MW]}, {0, 1, 1}]/
      (mass[MZ]^4*(-mass[MW] + mass[MZ])*(mass[MW] + mass[MZ])) + 
     mtad[{mass[MZ], 0, mass[MW]}, {1, 1, 1}]/mass[MW]^4 + 
     mtad[{mass[MZ], 0, mass[MW]}, {1, 1, 1}]/(mass[MW]^2*mass[MZ]^2) + 
     (((-2 + d)*mtad[{mass[MZ], 0, mass[MW]}, {1, 0, 1}])/
        (-mass[MW]^2 + mass[MZ]^2)^2 - ((-3 + d)*(mass[MW]^2 + mass[MZ]^2)*
         mtad[{mass[MZ], 0, mass[MW]}, {1, 1, 1}])/(-mass[MW]^2 + mass[MZ]^2)^
         2)/mass[MW]^2 + (mass[MZ]^2*mtad[{mass[MZ], mass[MW], mass[MW]}, 
        {1, 1, 1}])/(mass[MW]^4*(mass[MW] - mass[MZ])*
       (mass[MW] + mass[MZ])) + mtad[{mass[MZ], mass[MZ], mass[MW]}, 
       {1, 1, 1}]/(mass[MZ]^2*(-mass[MW] + mass[MZ])*(mass[MW] + mass[MZ]))))/
   (2048*cw^2*(-2 + d + d^2)*Pi^8*sw^2)}
